#!/bin/sh
. test/functions.sh
setup
install

# Test init command
expect 0 "npx --no-install husky init"

# After init, the default `npm test` script created by `npm init -y`
# exits with code 1 ("Error: no test specified"). The default pre-commit
# generated by `husky init` must not invoke it directly, otherwise
# `git commit` would always fail right after init. See issue #1473.
git add package.json .husky
expect 0 "git commit -m foo"
